import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"TCP 拥塞控制","description":"「网络慢」有很多种,拥塞是其中最容易被忽略的一种:链路没坏,但大家都在抢带宽。","frontmatter":{},"headers":[],"relativePath":"网络/22-tcp-congestion.md","filePath":"网络/22-tcp-congestion.md","lastUpdated":1793203221000}'),e={name:"网络/22-tcp-congestion.md"};function l(p,s,d,o,h,r){return t(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="tcp-拥塞控制" tabindex="-1">TCP 拥塞控制 <a class="header-anchor" href="#tcp-拥塞控制" aria-label="Permalink to &quot;TCP 拥塞控制&quot;">​</a></h1><blockquote><p>「网络慢」有很多种,拥塞是其中最容易被忽略的一种:链路没坏,但大家都在抢带宽。</p></blockquote><h2 id="一、两个不同的-堵" tabindex="-1">一、两个不同的&quot;堵&quot; <a class="header-anchor" href="#一、两个不同的-堵" aria-label="Permalink to &quot;一、两个不同的&quot;堵&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>原因</th><th>表现</th><th>解法</th></tr></thead><tbody><tr><td><strong>拥塞(congestion)</strong></td><td>网络中间的路由器队列满了,包被丢弃重传</td><td>RTT 抖动大、丢包率上升</td><td>拥塞控制算法</td></tr><tr><td><strong>带宽限制(bandwidth)</strong></td><td>物理链路容量有限</td><td>速率稳定在上限</td><td>升级带宽</td></tr></tbody></table><p>拥塞控制解决的是第一个。<strong>注意</strong>:链路利用率 100% 本身就是一种拥塞 —— 队列一满,延迟就会暴涨(排队时延)。</p><h2 id="二、四个阶段" tabindex="-1">二、四个阶段 <a class="header-anchor" href="#二、四个阶段" aria-label="Permalink to &quot;二、四个阶段&quot;">​</a></h2><h3 id="_1-慢启动-slow-start" tabindex="-1">1. 慢启动(Slow Start) <a class="header-anchor" href="#_1-慢启动-slow-start" aria-label="Permalink to &quot;1. 慢启动(Slow Start)&quot;">​</a></h3><p><code>cwnd</code>(拥塞窗口)从 1 个 MSS 开始,<strong>每个 RTT 翻倍</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwnd: 1 → 2 → 4 → 8 → 16 → 32 → 64 ...</span></span></code></pre></div><p>指数增长,目的是快速探测链路的最大容量。慢启动只在前几个 RTT 有效。</p><h3 id="_2-拥塞避免-congestion-avoidance" tabindex="-1">2. 拥塞避免(Congestion Avoidance) <a class="header-anchor" href="#_2-拥塞避免-congestion-avoidance" aria-label="Permalink to &quot;2. 拥塞避免(Congestion Avoidance)&quot;">​</a></h3><p><code>ssthresh</code> 达到后,改为<strong>每个 RTT 增加 1 个 MSS</strong>(线性增长)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwnd: 64 → 65 → 66 → 67 ...</span></span></code></pre></div><p>线性增长是为了避免再次把网络打爆。</p><h3 id="_3-快重传-fast-retransmit" tabindex="-1">3. 快重传(Fast Retransmit) <a class="header-anchor" href="#_3-快重传-fast-retransmit" aria-label="Permalink to &quot;3. 快重传(Fast Retransmit)&quot;">​</a></h3><p>接收方收到<strong>3 个重复 ACK</strong> 时,不等超时,立刻重传丢失的那个包。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送方发出 seq=1..8</span></span>
<span class="line"><span>接收方返回 ACK=4</span></span>
<span class="line"><span>发送方发出 seq=9,接收方回 ACK=4</span></span>
<span class="line"><span>发送方发出 seq=10,接收方回 ACK=4   ← 第 3 个重复 ACK</span></span>
<span class="line"><span>发送方立刻重传 seq=4              ← 快重传,不等 RTO</span></span></code></pre></div><h3 id="_4-快恢复-fast-recovery" tabindex="-1">4. 快恢复(Fast Recovery) <a class="header-anchor" href="#_4-快恢复-fast-recovery" aria-label="Permalink to &quot;4. 快恢复(Fast Recovery)&quot;">​</a></h3><p>发生丢包后,<code>cwnd</code> 不退回 1,而是<strong>减半</strong>(从 ssthresh 开始),继续线性增长。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssthresh = cwnd / 2</span></span>
<span class="line"><span>cwnd = ssthresh      ← 不回到 1,避免吞吐骤降</span></span></code></pre></div><h3 id="完整的-reno-状态机" tabindex="-1">完整的 Reno 状态机 <a class="header-anchor" href="#完整的-reno-状态机" aria-label="Permalink to &quot;完整的 Reno 状态机&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          慢启动                 拥塞避免</span></span>
<span class="line"><span>   cwnd=1 ──────────→ ssthresh ──────────→ </span></span>
<span class="line"><span>     ↑                                      │</span></span>
<span class="line"><span>     │                                      │ 3 重复 ACK</span></span>
<span class="line"><span>     │                                      ▼</span></span>
<span class="line"><span>     └──────────────  超时重传 ←───────── 快恢复</span></span>
<span class="line"><span>              cwnd=1, ssthresh = cwnd/2</span></span></code></pre></div><h2 id="三、拥塞窗口与发送窗口" tabindex="-1">三、拥塞窗口与发送窗口 <a class="header-anchor" href="#三、拥塞窗口与发送窗口" aria-label="Permalink to &quot;三、拥塞窗口与发送窗口&quot;">​</a></h2><p>实际能发多少,取两者的较小值:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送窗口 = min(cwnd, rwnd)</span></span>
<span class="line"><span>         └ 拥塞窗口   └ 接收窗口</span></span></code></pre></div><ul><li><code>cwnd</code>:网络能承受多少(拥塞控制决定)</li><li><code>rwnd</code>:对端接收缓冲区还能收多少(流量控制决定)</li></ul><p><strong>流量控制是「别把对方撑爆」,拥塞控制是「别把网络撑爆」</strong>,两者独立。</p><h2 id="四、cubic-与-bbr" tabindex="-1">四、CUBIC 与 BBR <a class="header-anchor" href="#四、cubic-与-bbr" aria-label="Permalink to &quot;四、CUBIC 与 BBR&quot;">​</a></h2><h3 id="cubic-默认" tabindex="-1">CUBIC(默认) <a class="header-anchor" href="#cubic-默认" aria-label="Permalink to &quot;CUBIC(默认)&quot;">​</a></h3><p>Linux 默认算法。用<strong>三次函数</strong>在 RTT 内做更激进的增长,靠近 ssthresh 时增长变缓。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>W(t) = C·(t - K)³ + W_max</span></span></code></pre></div><ul><li>优点:在高 BDP 链路上(比如 10Gbps)比 Reno 快得多</li><li>缺点:仍然是<strong>丢包驱动</strong>的,必须先丢包才知道拥塞了</li></ul><h3 id="bbr-bottleneck-bandwidth-and-rtt" tabindex="-1">BBR(Bottleneck Bandwidth and RTT) <a class="header-anchor" href="#bbr-bottleneck-bandwidth-and-rtt" aria-label="Permalink to &quot;BBR(Bottleneck Bandwidth and RTT)&quot;">​</a></h3><p>Google 提出,思路完全不同:<strong>不靠丢包检测拥塞,靠测带宽和 RTT</strong>。</p><p>维护两个模型:</p><ul><li><strong>BtlBw</strong>:瓶颈带宽(通过测量历史最大吞吐估计)</li><li>**RTprop\`:传播时延(历史最小 RTT 估计)</li></ul><p>然后用这两个值算出理想发送量:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BDP = BtlBw × RTprop</span></span></code></pre></div><p>发送速率围绕 BDP 做上下调节,始终<strong>留出 10% 的余量</strong>避免排满队列。</p><table tabindex="0"><thead><tr><th>对比</th><th>CUBIC</th><th>BBR</th></tr></thead><tbody><tr><td>拥塞信号</td><td>丢包</td><td>带宽和 RTT 测量</td></tr><tr><td>队列时延</td><td>高(填满队列才发)</td><td>低(主动留余量)</td></tr><tr><td>弱网表现</td><td>一般</td><td>好很多</td></tr><tr><td>部署成本</td><td>内核默认</td><td>需内核模块 / 云厂商支持</td></tr></tbody></table><p><strong>结论</strong>:BBR 在跨境、无线、丢包不严重的链路上体验明显更好;但它可能对下游不友好(抢带宽),所以在共享网络里要克制使用。</p><h2 id="五、实际调优" tabindex="-1">五、实际调优 <a class="header-anchor" href="#五、实际调优" aria-label="Permalink to &quot;五、实际调优&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看当前拥塞窗口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ti</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cwnd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux:启用 BBR</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;net.ipv4.tcp_congestion_control = bbr&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 增大初始拥塞窗口(BDP 大的链路)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net.ipv4.tcp_slow_start_after_idle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 提高 socket 缓冲区(高带宽高时延链路)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_buffer_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16k</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">proxy_buffers </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16k</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="六、怎么判断-我遇到的是拥塞" tabindex="-1">六、怎么判断&quot;我遇到的是拥塞&quot; <a class="header-anchor" href="#六、怎么判断-我遇到的是拥塞" aria-label="Permalink to &quot;六、怎么判断&quot;我遇到的是拥塞&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能是</th></tr></thead><tbody><tr><td>RTT 稳定但吞吐上不去</td><td>带宽瓶颈(正常,不是拥塞)</td></tr><tr><td>RTT 明显抖动 + 丢包</td><td>拥塞</td></tr><tr><td>同一时刻多台机器互相拖慢</td><td>共享链路的拥塞</td></tr><tr><td>大包全丢、小包正常</td><td>路径 MTU 黑洞(不是拥塞)</td></tr></tbody></table><p><strong>测量</strong>:用 <code>ping</code> 观察 RTT 波动,用 <code>mtr --tcp</code> 看路径上哪一跳开始丢包。</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><p><strong>Q1: 慢启动和拥塞避免的区别?</strong> 慢启动阶段 cwnd 每个 RTT 翻倍(指数增长),用于快速探测链路容量;达到 ssthresh 后进入拥塞避免,每个 RTT 只加 1 个 MSS(线性增长),避免把网络打爆。</p><p><strong>Q2: 快重传的触发条件?</strong> 接收方连续收到 3 个重复 ACK,发送方判定为丢包并立刻重传,不等 RTO 超时。</p><p><strong>Q3: 拥塞窗口和接收窗口的区别?</strong> cwnd 由拥塞控制算法决定,表示网络能承受多少;rwnd 由接收方的 TCP 栈决定,表示对端缓冲区还能收多少。实际发送窗口取两者较小值。前者防&quot;把网络撑爆&quot;,后者防&quot;把对方撑爆&quot;。</p><p><strong>Q4: BBR 和 CUBIC 的核心区别?</strong> CUBIC 是丢包驱动的:必须先丢包才知道拥塞了,代价是填满队列导致高时延。BBR 主动测量瓶颈带宽和最小 RTT,算出 BDP 后留 10% 余量发送,时延低且在弱网下表现更好。</p><p><strong>Q5: 怎么排查是不是拥塞?</strong> 看 RTT 是否明显抖动、丢包率是否上升,用 <code>mtr --tcp</code> 定位丢包起点。如果 RTT 稳定而吞吐上不去,那是带宽瓶颈而不是拥塞。</p><h2 id="📚-延伸阅读" tabindex="-1">📚 延伸阅读 <a class="header-anchor" href="#📚-延伸阅读" aria-label="Permalink to &quot;📚 延伸阅读&quot;">​</a></h2><ul><li><a href="/网络/15-tcp-handshake">TCP 三次握手与四次挥手</a></li><li><a href="/网络/">网络协议知识体系</a></li><li><a href="/网络/8-cache">HTTP 缓存机制</a></li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>拥塞控制和流量控制是两回事:一个防撑爆网络,一个防撑爆对端。</li><li>四个阶段:慢启动(指数)→ 拥塞避免(线性)→ 快重传(3 个重复 ACK)→ 快恢复(减半不归零)。</li><li>CUBIC 靠丢包检测拥塞,BBR 靠测带宽和 RTT,后者时延低、弱网表现好。</li><li>链路上还有第三类问题(MTU 黑洞)和第四类(带宽上限),排查时别混为一谈。</li></ul><h2 id="五、半连接与全连接" tabindex="-1">五、半连接与全连接 <a class="header-anchor" href="#五、半连接与全连接" aria-label="Permalink to &quot;五、半连接与全连接&quot;">​</a></h2><p>三次握手完成前,连接处于<strong>半连接状态</strong>:客户端已发出 SYN 并收到 SYN+ACK,但最后的 ACK 还没发出去(或者还没收到)。此时服务端会保留这个连接状态一段时间。</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>风险</th></tr></thead><tbody><tr><td><strong>半连接</strong></td><td>握手未完成</td><td>SYN Flood:攻击者发大量 SYN 但从不回 ACK,服务端半连接队列被占满</td></tr><tr><td><strong>全连接</strong></td><td>握手完成,可以传数据</td><td>正常的活跃连接</td></tr></tbody></table><p><strong>防护</strong>:</p><ul><li><strong>SYN Cookie</strong>:服务端不存半连接状态,把状态编码进 SYN+ACK 里,收到 ACK 时再解码还原。代价是丢失部分 TCP 选项</li><li><strong>限制半连接队列长度</strong>(<code>net.ipv4.tcp_max_syn_backlog</code>)</li><li><strong>SYN Flood 防护</strong>:限速 + 清洗</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看半连接队列</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SYN-RECV</span></span></code></pre></div>`,63)])])}const k=a(e,[["render",l]]);export{g as __pageData,k as default};
